// 1) Programmatic Lighthouse run against gif.ski
const lighthouse = require('lighthouse');
const chromeLauncher = require('lighthouse/chrome-launcher');
(async () => {
  const chrome = await chromeLauncher.launch({chromeFlags: ['--headless']});
  const options = {
    port: chrome.port,
    output: 'json',
    onlyCategories: ['byte-efficiency']
  };
  const runnerResult = await lighthouse('https://gif.ski/', options);
  const audit = runnerResult.lhr.audits['efficient-animated-content'];
  console.log('Byte savings (bytes):', audit.details.items[0].wastedBytes);
  console.log('Displayed score (should reflect ms savings):', runnerResult.lhr.categories['performance'].score);
  await chrome.kill();
})();

// 2) Minimal repro of the zero-ms bug in node-land
const WebInspector = require('lighthouse-core/lib/web-inspector');
const EfficientAnimatedContent = require('lighthouse-core/audits/byte-efficiency/efficient-animated-content');
const ByteEfficiencyAudit = require('lighthouse-core/audits/byte-efficiency/byte-efficiency-audit');
const NetworkNode = require('lighthouse-core/lib/dependency-graph/network-node');
const Simulator = require('lighthouse-core/lib/dependency-graph/simulator/simulator');

;(async () => {
  // 1. Fake a single large GIF network record
  const networkRecords = [{
    requestId: 1,
    _resourceType: WebInspector.resourceTypes.Image,
    _mimeType: 'image/gif',
    _resourceSize: 5046 * 1024,
    url: 'https://gif.ski/demo.gif',
    _transferSize: 5046 * 1024,
    _timing: {receiveHeadersEnd: 0},
    get transferSize() { return this._transferSize; }
  }];

  // 2. Audit animated content to get wastedBytes
  const artifacts = {devtoolsLogs: {defaultPass: []}};
  const {results} = await EfficientAnimatedContent.audit_(artifacts, networkRecords);
  console.log('wastedBytes (should be ~4.8 MB):', results[0].wastedBytes);

  // 3. Build a dependency graph with only a single network node and no CPU tasks
  const graph = new NetworkNode(networkRecords[0]);
  const simulator = new Simulator({});

  // 4. Produce the ByteEfficiencyAudit result (this uses computeWasteWithTTIGraph)
  const headings = ByteEfficiencyAudit.headings || [
    {key: 'totalBytes'}, {key: 'wastedBytes'}, {key: 'wastedMs'}
  ];
  const auditProduct = ByteEfficiencyAudit.createAuditProduct({headings, results}, graph, simulator);

  console.log('Calculated ms savings (rawValue):', auditProduct.rawValue);
  // rawValue will be 0, leading to a 100 score despite large byte savings
})();
